style.css:
@-moz-document url-prefix("https://gemini.google.com") {
/* ==UserStyle==
@name           Gemini Minimal Wide
@namespace      hd-o
@version        1.0.0
@description    Wider content and less shadows
@author         hadrian.dev
==/UserStyle== */

    :root {
        --gmw-border-color: #E5E5E5;
    }
        
    .conversation-container {
        max-width: calc(100vw - 40%) !important;
    }

    .table-block, user-query {
        max-width: 100% !important;
    }

    chat-window::before {
        background: none !important;
    }

    
    bard-sidenav:not(.collapsed) {
        width: 260px !important;
    }
    
    side-navigation-content {
        border-right: 1px solid var(--gmw-border-color) !important;
    }

    gem-nav-list-item a {
        border-radius: 10px !important;
    }

    mat-nav-list {
        gap: 2px !important;
    }

    input-area-v2 {
        box-shadow: none !important;
        border: 1px solid var(--gmw-border-color) !important;
    }
    
    side-navigation-content,
    input-container {
        background: none !important;
    }

    input-container {
        position: absolute !important;
        padding-bottom: 20px !important;
    }

    input-container::before {
        display: none !important;
    }

    hallucination-disclaimer {
        display: none !important;
    }
    
    infinite-scroller {
        padding-bottom: 100px !important;
    }
    
    @media (prefers-color-scheme: dark) {
        :root {
            --gmw-border-color: #222;
        }
        
        body {
            background: #050505 !important;
        }
        
        bard-sidenav {
            background: #050505 !important;
        }
    }
}
